import { GUIDE_SCOPE, REVIEWED_ON, LAYERS, DOMAINS, PLAYBOOKS, TOOLS, COMPONENTS, CONTRACTS, STATES, PHASES, MEASURES, DECISIONS } from './implementation-data.mjs';

export function createImplementationGuide(context) {
  const {ui,esc,icon,badge,button,pageHeader,openDialog,toast,render}=context;
  const tabs=[['strategy','Strategy & ownership'],['playbooks','Build playbooks'],['tools','Example tools'],['architecture','Architecture'],['delivery','Delivery plan']];
  ui.implementationTab='strategy';
  ui.implementationPillar='foundations';
  ui.toolFilter='all';
  ui.toolSearch='';
  const link=(path,label,kind='secondary')=>`<a class="btn ${kind}" href="#implementation/${path}">${label}${icon('arrow')}</a>`;
  const list=items=>`<ul class="implementation-list">${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
  const table=(head,rows,cls='')=>`<div class="table-wrap"><table class="implementation-table ${cls}"><thead><tr>${head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const sourceLinks=tool=>`<div class="implementation-sources">${tool.sources.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗<span class="sr-only"> (opens in a new tab)</span></a>`).join('')}</div>`;

  function applyRoute(tab,pillar) {
    ui.implementationTab=tabs.some(([key])=>key===tab)?tab:'strategy';
    if(PLAYBOOKS.some(p=>p.id===pillar))ui.implementationPillar=pillar;
  }
  function view() {
    return `<div class="implementation">${pageHeader('BUILD & OPERATE / CLOUD TRUST','Implementation guide','Translate the trust lifecycle into owned capabilities, integrations, and measurable outcomes.',`<a class="btn secondary" href="./cloud-trust-implementation.md" download>${icon('download')}Download guide</a>`)}
      <nav class="pillar-tabs implementation-tabs" aria-label="Implementation sections">${tabs.map(([key,label])=>`<a href="#implementation/${key}" class="${key===ui.implementationTab?'selected':''}" ${key===ui.implementationTab?'aria-current="page"':''}>${label}</a>`).join('')}</nav>
      <div class="implementation-notice">${icon('info')}<p><b>Proposed implementation.</b> ${esc(ui.implementationTab==='strategy'?'Aligned to your layered Cloud & Kubernetes strategy. Delivery responsibilities below are proposed mappings.':'The demo simulates the lifecycle. Tool integrations, backend services, and production controls described here remain to be implemented.')}</p><span class="badge gray">0 live integrations</span></div>
      ${({strategy,playbooks,tools:toolCatalog,architecture,delivery}[ui.implementationTab])()}
      <p class="implementation-reference-note">Official tool references reviewed ${REVIEWED_ON}. Candidate tools require confirmation of enterprise fit, licensing, permissions, and supported versions.</p></div>`;
  }
  function strategy() {
    return `<section class="implementation-hero"><div><span class="eyebrow">ONE EXPERIENCE · DISTRIBUTED DELIVERY</span><h2>Make trust continuous.<br>Keep ownership clear.</h2><p>Cloud Trust connects secure provisioning, temporary access, continuous assurance, and accountable governance across the application, platform, and infrastructure layers.</p>${link('playbooks','Explore the build playbooks','primary')}</div><div class="implementation-promises">${PLAYBOOKS.map(p=>`<a href="#implementation/playbooks/${p.id}"><span>${p.number}</span><div><b>${esc(p.title)}</b><small>${esc(p.promise)}</small></div>${icon('arrow')}</a>`).join('')}</div></section>
      <section class="panel"><div class="panel-heading"><div><h2>The layered vision</h2><p>Infrastructure products support platforms; platforms simplify the experience for application teams.</p></div>${badge('Strategy alignment','green')}</div><div class="implementation-layers">${LAYERS.map((l,i)=>`<article class="implementation-layer layer-${i}"><div><span class="eyebrow">${esc(l.audience)}</span><h3>${esc(l.name)}</h3><small>${esc(l.components)}</small></div><p>${esc(l.responsibility)}</p><div class="layer-contract"><b>Shared contract</b><span>${esc(l.contract)}</span></div></article>`).join('')}</div><div class="implementation-shared"><b>Cloud Trust connects every layer</b><span>Common workload identity</span><span>Policy & workflow</span><span>Linked evidence</span></div><p class="implementation-panel-note">The application entry point is shown as “ASC” in the strategy. Its meaning and integration boundary need confirmation; this guide leaves the acronym unexpanded.</p></section>
      <section class="panel"><div class="panel-heading"><div><h2>Four product pillars. Five delivery domains.</h2><p>A proposed mapping of the strategy’s teams to the customer experience.</p></div></div>${table(['Delivery domain','Primary pillar','Delivery responsibility','Shared handoff'],DOMAINS.map(d=>[d.name,d.lead,d.owns,d.handoff]),'ownership-table')}<p class="implementation-panel-note">Kubernetes retains its distinct platform mandate. IAM, product orchestration, and risk/control review provide the additional shared responsibilities needed to connect the five domains.</p></section>
      <div class="implementation-split"><section class="panel implementation-prose"><span class="eyebrow">PRODUCT RESPONSIBILITY</span><h2>What Cloud Trust owns</h2>${list(['A consistent customer experience and common workload identity.','Policy and decision contracts, cross-domain workflow, and connected evidence.','Visibility of coverage, unresolved exposure, accountable owners, and operational outcomes.'])}</section><section class="panel implementation-prose"><span class="eyebrow">DELIVERY RESPONSIBILITY</span><h2>What domain teams own</h2>${list(['Provider- and platform-specific engineering, enforcement, and support.','Authoritative signals, approved execution paths, and verified outcomes.','Specialist tooling, service health, change controls, and recovery procedures.'])}</section></div>`;
  }
  function playbooks() {
    const p=PLAYBOOKS.find(p=>p.id===ui.implementationPillar);
    return `<div class="implementation-pillar-picker" aria-label="Choose a pillar">${PLAYBOOKS.map(x=>`<a href="#implementation/playbooks/${x.id}" class="${p.id===x.id?'selected':''}" ${p.id===x.id?'aria-current="page"':''}><span>${x.number} ${icon(x.id)}</span><b>${esc(x.title)}</b><small>${esc(x.promise)}</small></a>`).join('')}</div>
      <section class="implementation-playbook-intro"><div><span class="eyebrow">PLAYBOOK ${p.number} / ${esc(p.promise.toUpperCase())}</span><h2>${esc(p.outcome)}</h2><p><b>Accountable delivery:</b> ${esc(p.owner)}</p></div><a class="btn secondary" href="#${p.id}">${icon('play')}Try this in the demo</a></section>
      <div class="implementation-workbench"><div><section class="panel"><div class="panel-heading"><div><h2>How to implement</h2><p>Six steps, with a reviewable output at each handoff.</p></div></div><ol class="implementation-steps">${p.steps.map(([title,body,output],i)=>`<li><details ${i===0?'open':''}><summary><span class="step-index">${String(i+1).padStart(2,'0')}</span><b>${esc(title)}</b>${icon('chevron')}</summary><div><p>${esc(body)}</p><p class="step-output"><b>Output</b>${esc(output)}</p></div></details></li>`).join('')}</ol></section>
      <section class="panel implementation-example"><div class="panel-heading"><div><h2>${esc(p.exampleTitle)}</h2><p>${esc(p.exampleNote)}</p></div>${button('Copy example','implementation-copy','secondary','','data-id="'+p.id+'"')}</div><pre tabindex="0" aria-label="${esc(p.exampleTitle)}"><code>${esc(p.example)}</code></pre></section></div>
      <aside class="implementation-aside"><section class="panel implementation-prose"><span class="eyebrow">BEFORE YOU START</span><h3>Prerequisites</h3>${list(p.prerequisites)}</section><section class="panel implementation-prose"><span class="eyebrow">EXAMPLE INTEGRATIONS</span><h3>Tools in this playbook</h3><div class="implementation-tool-links">${p.tools.map(id=>{const t=TOOLS.find(x=>x.id===id);return `<button data-action="implementation-tool" data-id="${t.id}"><span><b>${esc(t.name)}</b><small>${esc(t.category)}</small></span>${icon('chevron')}</button>`;}).join('')}</div></section><section class="panel implementation-prose"><span class="eyebrow">ACCEPTANCE GATE</span><h3>Prove it works</h3>${list(p.verify)}</section></aside></div>
      <section class="implementation-demo-note">${icon('play')}<div><b>Demonstrate the outcome</b><p>${esc(p.demo)}</p></div><a class="text-button" href="#${p.id}">Open ${esc(p.title)} ${icon('arrow')}</a></section>`;
  }
  function toolCatalog() {
    const query=ui.toolSearch.trim().toLowerCase();
    const filtered=TOOLS.filter(t=>(ui.toolFilter==='all'||t.pillars.includes(ui.toolFilter))&&[t.name,t.role,t.category,t.owner,t.layer].join(' ').toLowerCase().includes(query));
    return `<section class="implementation-catalog-intro"><div><h2>A connected platform, using the tools you choose.</h2><p>These ${TOOLS.length} examples illustrate the integration roles. Select the capabilities that fit your existing estate; you do not need every product in the catalog.</p></div>${link('architecture','See the integration contracts')}</section>
      <form class="implementation-filters" id="implementation-search-form"><label class="field">Search tools<input id="implementation-tool-search" name="query" type="search" value="${esc(ui.toolSearch)}" placeholder="Name, capability, or owner"></label><label class="field">Product pillar<select id="implementation-tool-filter">${[['all','All four pillars'],...PLAYBOOKS.map(p=>[p.id,p.title])].map(([v,l])=>`<option value="${v}" ${v===ui.toolFilter?'selected':''}>${esc(l)}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Search</button><span role="status">${filtered.length} of ${TOOLS.length} examples</span>${ui.toolSearch||ui.toolFilter!=='all'?button('Clear filters','implementation-clear','ghost'):''}</form>
      <div class="implementation-tool-grid">${filtered.map(t=>`<article class="panel implementation-tool-card"><div class="tool-card-meta"><span class="eyebrow">${esc(t.category)}</span>${badge('Candidate','gray')}</div><h3>${esc(t.name)}</h3><p>${esc(t.role)}</p><div class="tool-pillar-tags">${t.pillars.map(id=>`<span>${esc(PLAYBOOKS.find(p=>p.id===id).title.replace('Cloud ',''))}</span>`).join('')}</div><dl><dt>Delivery owner</dt><dd>${esc(t.owner)}</dd><dt>Integration layer</dt><dd>${esc(t.layer)}</dd></dl>${button('How to integrate','implementation-tool','secondary','arrow','data-id="'+t.id+'"')}</article>`).join('')}</div>${filtered.length?'':`<div class="panel implementation-prose"><h3>No matching examples</h3><p>Try another capability or clear the filters to see the complete catalog.</p>${button('Clear filters','implementation-clear','secondary')}</div>`}`;
  }
  function showTool(id) {
    const t=TOOLS.find(t=>t.id===id);if(!t)return;
    openDialog(esc(t.name),`<div class="implementation-tool-detail">${badge('Example candidate · Not connected','gray')}<p class="modal-intro">${esc(t.role)}</p><dl class="finding-facts"><div><dt>Accountable owner</dt><dd>${esc(t.owner)}</dd></div><div><dt>Integration layer</dt><dd>${esc(t.layer)}</dd></div></dl><div class="implementation-exchange">${esc(t.exchange)}</div><h3>How to integrate</h3><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="implementation-consideration"><b>Implementation consideration</b><p>${esc(t.caution)}</p></div><h3>Official documentation</h3>${sourceLinks(t)}<p class="form-note">Capability references reviewed ${REVIEWED_ON}. Steps are a proposed Cloud Trust integration design. Confirm the selected tenant, supported version, and permissions before implementation.</p></div>`,button('Close','close','secondary'),'implementation-tool-modal');
  }
  function architecture() {
    return `<section class="implementation-architecture-intro"><span class="eyebrow">REFERENCE DESIGN / TO BE BUILT</span><h2>One decision trail, from request to confirmed enforcement.</h2><p>The authenticated backend joins identity, task, workload, and policy context. Durable workflows call the domain adapters, verify actual outcomes, and retain the evidence. Cloud credentials stay on the server.</p></section>
      <section class="panel"><div class="panel-heading"><div><h2>Services and ownership</h2><p>Shared contracts connect independently operated capabilities.</p></div></div>${table(['Component','Delivery owner','Responsibility'],COMPONENTS)}</section>
      <section class="panel"><div class="panel-heading"><div><h2>Minimum integration contracts</h2><p>Proposed internal records; adapters translate each vendor’s supported API.</p></div></div>${table(['Contract','Minimum fields','Required behavior'],CONTRACTS)}</section>
      <section class="panel"><div class="panel-heading"><div><h2>Temporary access: implement the full lifecycle</h2><p>Keep a request, an approval, and a confirmed provider result distinguishable.</p></div></div>${table(['Transition','Action','Failure behavior'],STATES)}</section>
      <div class="implementation-split"><section class="panel implementation-prose"><span class="eyebrow">RELIABLE INTEGRATIONS</span><h3>Build for reconciliation</h3>${list(['Use stable idempotency keys, bounded retries, backoff, dead-letter handling, and scheduled reconciliation.','Authenticate events and validate schema, source scope, ordering, and timestamps. Preserve native IDs and evidence links.','Separate read-only observation from write / execution identities, with connector credentials in a server-side secret store.','Recheck current trust and resource version before high-impact actions. Halt automation on a scope mismatch.'])}</section><section class="panel implementation-prose"><span class="eyebrow">VERIFIED ENFORCEMENT</span><h3>Measure the actual outcome</h3>${list(['A successful API call or closed ticket does not prove that access was removed or a finding resolved.','Provider tokens, role models, and propagation require separate tests and removal objectives for each adapter.','Record requested and confirmed timestamps; show pending failures and residual exposure to the accountable owner.','Use a separately authorized and reviewed emergency access path when normal recovery is unavailable.'])}</section></div>
      <section class="implementation-demo-note">${icon('info')}<div><b>From simulation to a production service</b><p>This demo stores synthetic state in the page. Production requires authenticated backend authorization, durable data, real reviewer separation, background workers, protected evidence retention, source reconciliation, and recovery operations. The demo’s JSON export is an ordinary snapshot.</p></div></section>`;
  }
  function delivery() {
    return `<section class="implementation-catalog-intro"><div><span class="eyebrow">INCREMENTAL DELIVERY</span><h2>Start with one complete workload path.</h2><p>Expand by verified outcomes. These phases are proposed delivery gates, with sequencing that preserves the strategy’s specialist ownership.</p></div>${link('playbooks','Open the playbooks')}</section>
      <div class="implementation-phases">${PHASES.map(p=>`<section class="panel implementation-phase"><div class="phase-marker">${p.number}</div><div><span class="eyebrow">${esc(p.scope)}</span><h3>${esc(p.title)}</h3><p class="phase-owners"><b>Owners:</b> ${esc(p.owners)}</p>${list(p.work)}<div class="phase-gate"><b>Exit gate</b><p>${esc(p.gate)}</p></div></div></section>`).join('')}</div>
      <section class="panel"><div class="panel-heading"><div><h2>Measure trust as an operational outcome</h2><p>Agree scope, freshness, and measurement windows before setting targets.</p></div></div>${table(['Measure','Proposed definition'],MEASURES)}</section>
      <section class="panel implementation-prose"><span class="eyebrow">DECISIONS TO VALIDATE</span><h3>Turn the proposed design into an agreed implementation</h3>${list(DECISIONS)}<p class="implementation-panel-note">${esc(GUIDE_SCOPE)}</p></section>`;
  }
  function action(name,id) {
    if(name==='implementation-tool'){showTool(id);return true;}
    if(name==='implementation-clear'){ui.toolSearch='';ui.toolFilter='all';render();return true;}
    if(name==='implementation-copy'){
      const p=PLAYBOOKS.find(p=>p.id===id);if(!p)return true;
      const fallback=()=>{openDialog('Copy implementation example',`<p class="modal-intro">Select and copy the example below.</p><pre class="policy-code" tabindex="0"><code>${esc(p.example)}</code></pre>`,button('Close','close'));};
      if(globalThis.navigator?.clipboard?.writeText)navigator.clipboard.writeText(p.example).then(()=>toast('Implementation example copied.')).catch(fallback);else fallback();
      return true;
    }
    return false;
  }
  function change(target) {
    if(target.id!=='implementation-tool-filter')return false;
    ui.toolSearch=document.querySelector('#implementation-tool-search')?.value||'';
    ui.toolFilter=target.value;render();document.querySelector('#implementation-tool-filter')?.focus();return true;
  }
  function submit(event) {
    if(event.target.id!=='implementation-search-form')return false;
    event.preventDefault();ui.toolSearch=document.querySelector('#implementation-tool-search').value;render();document.querySelector('#implementation-tool-search')?.focus();return true;
  }
  return {view,applyRoute,action,change,submit};
}
